package main

import (
	"net/http"
	"os"
	"path/filepath"
	"testing"
)

func TestTransferAcceptsProductionWindowsFolderZIP(t *testing.T) {
	// Generated by FileTransferPackage.CreateFolderAsync on Windows/.NET 10.
	// Keep a real cross-language fixture: Go-created ZIPs alone cannot prove
	// compatibility with the directory flags and data descriptors Windows emits.
	data, err := os.ReadFile("testdata/windows-folder.zip")
	if err != nil {
		t.Fatal(err)
	}
	receiver, token, _ := transferFixture(t)
	w := receiveFixture(receiver, transferRequest(token, "Clips", "folder", data))
	if w.Code != http.StatusOK {
		t.Fatalf("Windows folder ZIP rejected: %d %s", w.Code, w.Body)
	}
	contents, err := os.ReadFile(filepath.Join(receiver.root, "Clips", "nested", "café.txt"))
	if err != nil || string(contents) != "Synthetic Windows folder fixture.\n" {
		t.Fatalf("Windows folder content changed: %q %v", contents, err)
	}
	info, err := os.Stat(filepath.Join(receiver.root, "Clips", "empty"))
	if err != nil || !info.IsDir() {
		t.Fatalf("Windows empty directory missing: %v", err)
	}
}
